#!/usr/bin/env python3
"""Regenerate converted/Prove2me/Audit.lean: `#print axioms` for every converted prove2.me
solution theorem (`Prove2me.Solution.*`) and for the platform statement it proves."""
import re, pathlib
root = pathlib.Path(__file__).resolve().parent.parent / 'converted'
lines = ['/-',
 'Axiom audit of the converted prove2.me imports (BOOKPROOF_SPLIT_PLAN.md Phase 1.5, step 4).',
 'Acceptance: every line reports only `propext`, `Classical.choice`, `Quot.sound`.',
 'Build with `lake build Prove2me.Audit`.  Generated by `scripts/prove2me_audit.py`.',
 '-/', 'import Prove2me', '']
n = 0
for f in sorted((root / 'Prove2me').glob('*/*.lean')):
    if f.parent.name == 'Shim':
        continue
    s = f.read_text()
    m = re.search(r'original name\s*:\s*`([^`]+)`', s)
    sols = re.findall(r"theorem _root_\.(Prove2me\.Solution\.[A-Za-z0-9_'.]*[A-Za-z0-9_'])", s)
    lines.append(f'-- {f.relative_to(root)}')
    if m:
        lines.append(f'#print axioms {m.group(1)}')
    for x in sols:
        lines.append(f'#print axioms {x}')
    n += 1
(root / 'Prove2me' / 'Audit.lean').write_text('\n'.join(lines) + '\n')
print(n, 'files')
